	{
		# eclean.gg: Power & DPC Latency & CPU Core Parking (All cores unparked, P-Core priority, EPP 0)
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Control\Session Manager\Kernel" /v "ThreadDpcEnable" /t REG_DWORD /d 1 /f;
		$pwr = "HKLM\SOFTWARE\Policies\Microsoft\Power\PowerSettings";
		reg.exe add "$pwr\0cc5b647-c74e-4111-92e3-3b129533f4d5" /v "ACSettingIndex" /t REG_DWORD /d 100 /f;
		reg.exe add "$pwr\0cc5b647-c74e-4111-92e3-3b129533f4d5" /v "DCSettingIndex" /t REG_DWORD /d 100 /f;
		reg.exe add "$pwr\ea0653f4-9251-4ca4-99a3-324b3d2b0636" /v "ACSettingIndex" /t REG_DWORD /d 100 /f;
		reg.exe add "$pwr\ea0653f4-9251-4ca4-99a3-324b3d2b0636" /v "DCSettingIndex" /t REG_DWORD /d 100 /f;
		reg.exe add "$pwr\36687f9e-e3a5-4dbf-b1dc-15eb381c6863" /v "ACSettingIndex" /t REG_DWORD /d 0 /f;
		reg.exe add "$pwr\36687f9e-e3a5-4dbf-b1dc-15eb381c6863" /v "DCSettingIndex" /t REG_DWORD /d 0 /f;
		reg.exe add "$pwr\93b22d1d-9513-4bc7-ad42-1e967313f2e4" /v "ACSettingIndex" /t REG_DWORD /d 2 /f;
		reg.exe add "$pwr\bae08b81-2d5e-4688-ad6a-13243356654b" /v "ACSettingIndex" /t REG_DWORD /d 2 /f;
		reg.exe add "$pwr\be337238-0d82-4146-a960-4f3749d470c2" /v "ACSettingIndex" /t REG_DWORD /d 2 /f;
	};
	{
		# Zero-Click Setup Completion (Prevents 'Windows could not complete installation' Shift+F10 prompt)
		reg.exe add "HKLM\SYSTEM\Setup\Status\ChildCompletion" /v "setup.exe" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\Setup\Status\ChildCompletion" /v "audit.exe" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\Setup\Status\ChildCompletion" /v "oobe.exe" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\Setup" /v "SetupType" /t REG_DWORD /d 0 /f;
		reg.exe add "HKLM\SYSTEM\Setup" /v "SystemSetupInProgress" /t REG_DWORD /d 0 /f;
		reg.exe add "HKLM\SYSTEM\Setup" /v "OOBEInProgress" /t REG_DWORD /d 0 /f;
		reg.exe add "HKLM\SYSTEM\Setup\Status\SysprepStatus" /v "CleanupState" /t REG_DWORD /d 2 /f;
		reg.exe add "HKLM\SYSTEM\Setup\Status\SysprepStatus" /v "GeneralizationState" /t REG_DWORD /d 7 /f;
	};
	{
		# OEM Information & Model Branding
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\OEMInformation" /v "Manufacturer" /t REG_SZ /d "nano11 Project" /f;
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\OEMInformation" /v "Model" /t REG_SZ /d "nano11 Ultra-Light Edition" /f;
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\OEMInformation" /v "SupportURL" /t REG_SZ /d "https://github.com/gh459/nano11" /f;
	};
	{
		# Enable MSI (Message Signaled Interrupts) across target high-performance PCI device classes (GPU, NVMe, NIC)
		try {
			$targetClasses = @(
				'{4d36e968-e325-11ce-bfc1-08002be10318}', # Display / GPU
				'{4d36e972-e325-11ce-bfc1-08002be10318}', # Network Adapters (NIC)
				'{4d36e97b-e325-11ce-bfc1-08002be10318}'  # SCSIAdapter / NVMe Storage Controllers
			);
			Get-ChildItem -Path "HKLM:\SYSTEM\CurrentControlSet\Enum\PCI" -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -eq "Device Parameters" } | ForEach-Object {
				$parentPath = Split-Path -Path $_.PSPath -Parent;
				$classGuid = (Get-ItemProperty -Path $parentPath -Name "ClassGUID" -ErrorAction SilentlyContinue).ClassGUID;
				if (-not $classGuid -or ($targetClasses -contains $classGuid)) {
					$msiPath = Join-Path -Path $_.PSPath -ChildPath "Interrupt Management\MessageSignaledInterruptProperties";
					New-Item -Path $msiPath -Force -ErrorAction SilentlyContinue | Out-Null;
					Set-ItemProperty -Path $msiPath -Name "MSISupported" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue;
				}
			}
		} catch {}
	};
	{
		# HAGS (Hardware Accelerated GPU Scheduling) Default Enabled & Driver Exclusion
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Control\GraphicsDrivers" /v "HwSchMode" /t REG_DWORD /d 2 /f;
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate" /v "ExcludeWUDriversInQualityUpdate" /t REG_DWORD /d 1 /f;
	};
	{
		# Japanese IME & Input Telemetry Cloud Opt-Out
		reg.exe add "HKLM\SOFTWARE\Microsoft\Input\Settings" /v "EnableCloudCandidate" /t REG_DWORD /d 0 /f;
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\InputPersonalization" /v "AllowInputPersonalization" /t REG_DWORD /d 0 /f;
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\InputPersonalization" /v "RestrictImplicitInkCollection" /t REG_DWORD /d 1 /f;
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\InputPersonalization" /v "RestrictImplicitTextCollection" /t REG_DWORD /d 1 /f;
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Activity 'Running scripts to customize your Windows installation. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command "{0}".' -f $(
      $str = $script.ToString().Trim() -replace '\s+', ' ';
      $max = 100;
      if( $str.Length -le $max ) {
        $str;
      } else {
        $str.Substring( 0, $max - 1 ) + '...';
      }
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 >> "C:\Windows\Setup\Scripts\Specialize.log";

$scripts = @(
