		Set-ItemProperty -LiteralPath 'Registry::HKCU\Control Panel\Desktop' -Name 'ScreenSaverIsSecure' -Type 'String' -Value '0' -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Control Panel\Desktop' -Name 'UserPreferencesMask' -Type 'Binary' -Value ([byte[]](0x90,0x12,0x01,0x80,0x10,0x00,0x00,0x00)) -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Control Panel\Desktop' -Name 'DragFullWindows' -Type 'String' -Value '0' -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'TaskbarAnimations' -Type 'DWord' -Value 0 -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'ListviewAlphaSelect' -Type 'DWord' -Value 0 -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name 'ListviewShadow' -Type 'DWord' -Value 0 -Force;
