		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Narrator' -Name 'WinEnterLaunchNarrator' -Type 'DWord' -Value 0 -Force;
		Set-ItemProperty -LiteralPath 'Registry::HKCU\Software\Microsoft\Narrator' -Name 'NoStartNarratorShortcut' -Type 'DWord' -Value 1 -Force;
