& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Activity 'Running scripts to configure this user account. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command "{0}".' -f $(
      $str = $script.ToString().Trim() -replace '\s+', ' ';
      $max = 100;
      if( $str.Length -le $max ) {
        $str;
      } else {
        $str.Substring( 0, $max - 1 ) + '...';
      }
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 >> "$env:TEMP\UserOnce.log";

$scripts = @(
	{
		$names = @(
		  'ContentDeliveryAllowed';
		  'FeatureManagementEnabled';
		  'OEMPreInstalledAppsEnabled';
		  'PreInstalledAppsEnabled';
		  'PreInstalledAppsEverEnabled';
		  'SilentInstalledAppsEnabled';
		  'SoftLandingEnabled';
		  'SubscribedContentEnabled';
		  'SubscribedContent-310093Enabled';
		  'SubscribedContent-338387Enabled';
		  'SubscribedContent-338388Enabled';
		  'SubscribedContent-338389Enabled';
		  'SubscribedContent-338393Enabled';
		  'SubscribedContent-353694Enabled';
		  'SubscribedContent-353696Enabled';
		  'SubscribedContent-353698Enabled';
		  'SystemPaneSuggestionsEnabled';
		);
		
		foreach( $name in $names ) {
		  reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" /v $name /t REG_DWORD /d 0 /f;
		}
	};
	{
				# Revo Registry Cleaner Default User optimizations
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer" /v "link" /t REG_BINARY /d "00000000" /f;
		reg.exe add "HKU\DefaultUser\Control Panel\Desktop" /v "PaintDesktopVersion" /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "TaskbarAl" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "ExtendedUIHoverTime" /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "DesktopLivePreviewHoverTime" /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\AutoComplete" /v "Append Completion" /t REG_SZ /d "yes" /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\AutoComplete" /v "AutoSuggest" /t REG_SZ /d "yes" /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "LaunchTo" /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "ShowDriveLettersFirst" /t REG_DWORD /d 4 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\OperationStatusManager" /v "ConfirmationCheckBoxDoForAll" /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "ShowInfoTip" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "FolderContentsInfoTip" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Control Panel\Desktop" /v "AutoEndTasks" /t REG_SZ /d "1" /f;
		reg.exe add "HKU\DefaultUser\Control Panel\Desktop" /v "HungAppTimeout" /t REG_SZ /d "1000" /f;
		reg.exe add "HKU\DefaultUser\Control Panel\Desktop" /v "WaitToKillAppTimeout" /t REG_SZ /d "2000" /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer" /v "AltTabSettings" /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications" /v "GlobalUserDisabled" /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Policies\Attachments" /v "SaveZoneInformation" /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize" /v "EnableTransparency" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize" /v "AppsUseLightTheme" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize" /v "SystemUsesLightTheme" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Input\Settings" /v "EnableCloudCandidate" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\DWM" /v "ColorizationOpaqueBlend" /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Control Panel\Desktop\WindowMetrics" /v "MinAnimate" /t REG_SZ /d "0" /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects" /v "VisualFXSetting" /t REG_DWORD /d 2 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "TaskbarDa" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "TaskbarMn" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "ShowTaskViewButton" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "ShowCopilotButton" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\GameDVR" /v "AppCaptureEnabled" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\System\GameConfigStore" /v "GameDVR_Enabled" /t REG_DWORD /d 0 /f;
		reg.exe delete "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Run" /v "OneDrive" /f 2>$null;
		reg.exe delete "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Run" /v "OneDriveSetup" /f 2>$null;
		reg.exe add "HKU\DefaultUser\Control Panel\Desktop" /v "UserPreferencesMask" /t REG_BINARY /d "9012018010000000" /f;
		reg.exe add "HKU\DefaultUser\Control Panel\Desktop" /v "FontSmoothing" /t REG_SZ /d "2" /f;
		reg.exe add "HKU\DefaultUser\Control Panel\Desktop" /v "DragFullWindows" /t REG_SZ /d "0" /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "TaskbarAnimations" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "ListviewAlphaSelect" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "ListviewShadow" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced" /v "DisableThumbnailCache" /t REG_DWORD /d 1 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\DWM" /v "AlwaysHibernateThumbnails" /t REG_DWORD /d 0 /f;
		reg.exe add "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\RunOnce" /v "UnattendedSetup" /t REG_SZ /d "powershell.exe -ExecutionPolicy Bypass -NoProfile -NonInteractive -WindowStyle Hidden -Command \""Get-Content -LiteralPath 'C:\Windows\Setup\Scripts\UserOnce.ps1' -Raw | Invoke-Expression;\""" /f;
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Activity "Running scripts to modify the default user's registry hive. Do not close this window." -PercentComplete $complete;
    '*** Will now execute command "{0}".' -f $(
      $str = $script.ToString().Trim() -replace '\s+', ' ';
      $max = 100;
      if( $str.Length -le $max ) {
        $str;
      } else {
        $str.Substring( 0, $max - 1 ) + '...';
      }
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 >> "C:\Windows\Setup\Scripts\DefaultUser.log";

$scripts = @(
	{
		# Guarantee User account has NO password (completely blank) and cannot expire
		try {
			& net.exe accounts /maxpwage:UNLIMITED /minpwlen:0 2>$null;
			& net.exe user User "" /active:yes /passwordreq:no /expires:never 2>$null;
		} catch {}

		try {
			$emptySec = ConvertTo-SecureString "" -AsPlainText -Force;
			Set-LocalUser -Name "User" -Password $emptySec -PasswordNeverExpires $true -UserMayNotChangePassword $false -ErrorAction SilentlyContinue;
		} catch {}

		try {
			& net.exe user Administrator "" /active:yes /passwordreq:no /expires:never 2>$null;
		} catch {}

		# Configure persistent AutoAdminLogon with blank password
		Set-ItemProperty -LiteralPath 'Registry::HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'AutoAdminLogon' -Type 'String' -Force -Value '1';
		Set-ItemProperty -LiteralPath 'Registry::HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'DefaultUserName' -Type 'String' -Force -Value 'User';
		Set-ItemProperty -LiteralPath 'Registry::HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'DefaultPassword' -Type 'String' -Force -Value '';
		Set-ItemProperty -LiteralPath 'Registry::HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'ForceAutoLogon' -Type 'String' -Force -Value '1';
		Remove-ItemProperty -LiteralPath 'Registry::HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'AutoLogonCount' -Force -ErrorAction SilentlyContinue;

		# Disable lock screen password requirements on wake/idle
		try {
			& powercfg.exe /SETACVALUEINDEX SCHEME_CURRENT SUB_NONE CONSOLELOCK 0 2>$null;
			& powercfg.exe /SETDCVALUEINDEX SCHEME_CURRENT SUB_NONE CONSOLELOCK 0 2>$null;
		} catch {}
		reg.exe add "HKLM\SOFTWARE\Policies\Microsoft\Windows\System" /v "AllowDomainDelayLock" /t REG_DWORD /d 1 /f 2>$null;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Control\Lsa" /v "LimitBlankPasswordUse" /t REG_DWORD /d 0 /f 2>$null;
	};
	{
		Disable-ComputerRestore -Drive 'C:\';
	};
	{
		cmd.exe /c "rmdir C:\Windows.old";
	};
	{
		# Run CompactOS compression asynchronously in background to ensure zero desktop delay
		Start-Process -FilePath "compact.exe" -ArgumentList "/CompactOS:always" -WindowStyle Hidden -ErrorAction SilentlyContinue;
	};
	{
		# Radical RAM: Protected diagnostic, telemetry, and background services configured to Disabled (4) / Manual (3) as SYSTEM
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\DPS" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\WdiServiceHost" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\WdiSystemHost" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\FontCache" /v "Start" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\FontCache3.0.0.0" /v "Start" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\SCardSvr" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\ScDeviceEnum" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\icssvc" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\CertPropSvc" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\CscService" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\Netlogon" /v "Start" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\WpnService" /v "Start" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\WpnUserService" /v "Start" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\PimIndexMaintenanceSvc" /v "Start" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\UnistoreSvc" /v "Start" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\UserDataSvc" /v "Start" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\MessagingService" /v "Start" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\iphlpsvc" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\VaultSvc" /v "Start" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\TokenBroker" /v "Start" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\WbioSrvc" /v "Start" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\PhoneSvc" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\WpcMonSvc" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\WMPNetworkSvc" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\SmsRouter" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\AppHostSvc" /v "Start" /t REG_DWORD /d 3 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\SEMgrSvc" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\edgeupdate" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\edgeupdatem" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\GraphicsPerfSvc" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\InventorySvc" /v "Start" /t REG_DWORD /d 4 /f;
	};
	{
		# Radical RAM: Disable Application Prelaunch and enable memory tuning
		try {
			Disable-MMAgent -ApplicationPreLaunch -ErrorAction SilentlyContinue | Out-Null;
			Disable-MMAgent -ApplicationLaunchPrefetching -ErrorAction SilentlyContinue | Out-Null;
			Disable-MMAgent -OperationAPI -ErrorAction SilentlyContinue | Out-Null;
			Enable-MMAgent -PageCombining -ErrorAction SilentlyContinue | Out-Null;
			if (Test-Path "C:\Windows\Setup\Scripts\disable-memcompression.flag") {
				Disable-MMAgent -MemoryCompression -ErrorAction SilentlyContinue | Out-Null;
			}
		} catch {}
	};
	{
		# Radical RAM & Background Process Reduction: Disable high-memory, diagnostic, and census scheduled tasks
		schtasks.exe /change /tn "\Microsoft\Windows\MemoryDiagnostic\ProcessMemoryDiagnosticEvents" /disable 2>$null;
		schtasks.exe /change /tn "\Microsoft\Windows\MemoryDiagnostic\RunFullMemoryDiagnostic" /disable 2>$null;
		schtasks.exe /change /tn "\Microsoft\Windows\Maintenance\WinSAT" /disable 2>$null;
		schtasks.exe /change /tn "\Microsoft\Windows\DiskFootprint\Diagnostics" /disable 2>$null;
		schtasks.exe /change /tn "\Microsoft\Windows\Application Experience\Microsoft Compatibility Appraiser" /disable 2>$null;
		schtasks.exe /change /tn "\Microsoft\Windows\Application Experience\ProgramDataUpdater" /disable 2>$null;
		schtasks.exe /change /tn "\Microsoft\Windows\Application Experience\StartupAppTask" /disable 2>$null;
		schtasks.exe /change /tn "\Microsoft\Windows\Customer Experience Improvement Program\Consolidator" /disable 2>$null;
		schtasks.exe /change /tn "\Microsoft\Windows\Customer Experience Improvement Program\UsbCeip" /disable 2>$null;
		schtasks.exe /change /tn "\Microsoft\Windows\Device Information\Device" /disable 2>$null;
		schtasks.exe /change /tn "\Microsoft\Windows\DiskDiagnostic\Microsoft-Windows-DiskDiagnosticDataCollector" /disable 2>$null;
		schtasks.exe /change /tn "\Microsoft\Windows\Feedback\Siuf\DmClient" /disable 2>$null;
		schtasks.exe /change /tn "\Microsoft\Windows\Feedback\Siuf\DmClientOnScenarioDownload" /disable 2>$null;
	};
	{
		# Windows Security & Defender: complete user-mode service, task & cache purge (only when Defender was removed)
		if (-not (Test-Path 'C:\Program Files\Windows Defender\MsMpEng.exe')) {
			reg.exe delete "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Run" /v "SecurityHealth" /f 2>$null;
			$defSvcs = @('WinDefend', 'Sense', 'SecurityHealthService', 'wscsvc', 'webthreatdefsvc', 'webthreatdefusersvc');
			foreach ($s in $defSvcs) {
				reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\$s" /v "Start" /t REG_DWORD /d 4 /f 2>$null;
			}
			Stop-Process -Name "SecurityHealthSystray", "SecurityHealthHost", "MsMpEng", "NisSrv" -Force -ErrorAction SilentlyContinue;
			$defCaches = @(
				'C:\ProgramData\Microsoft\Windows Defender\Definition Updates',
				'C:\ProgramData\Microsoft\Windows Defender\Scans'
			);
			foreach ($dc in $defCaches) {
				if (Test-Path -LiteralPath $dc) {
					Remove-Item -LiteralPath $dc -Recurse -Force -ErrorAction SilentlyContinue;
				}
			}
			Get-ScheduledTask -TaskPath "\Microsoft\Windows\Windows Defender\*" -ErrorAction SilentlyContinue | Disable-ScheduledTask -ErrorAction SilentlyContinue | Out-Null;
		}
	};
	{
		# eclean & AtlasOS: Reset and disable Fault Tolerant Heap (FTH)
		try {
			rundll32.exe fthsvc.dll,FthSysprepSpecialize 2>$null;
		} catch {}
	};
	{
		# eclean & AtlasOS: Automatic Disk Cleanup & Junk Purge
		# Purge user and system temp folders, crash dumps, and minidumps
		foreach ($p in @($env:TEMP, $env:TMP, "$env:LOCALAPPDATA\Temp", "$env:WINDIR\Temp", "$env:LOCALAPPDATA\CrashDumps", "$env:WINDIR\Minidump")) {
			if (Test-Path $p) {
				Get-ChildItem -Path $p -Recurse -Force -ErrorAction SilentlyContinue | Remove-Item -Force -Recurse -ErrorAction SilentlyContinue;
			}
		}
	};
	{
		# AtlasOS & ReviOS: Complete Hibernation Purge (Frees RAM-sized GBs from disk)
		try {
			& powercfg.exe /hibernate off 2>$null;
		} catch {}
	};
	{
		# AtlasOS & ReviOS: Ultimate Performance or High Performance Power Plan Activation
		try {
			$uPlan = & powercfg.exe -duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61 2>$null;
			if ($uPlan -match '([a-f0-9-]{36})') {
				& powercfg.exe -setactive $matches[1] 2>$null;
			} else {
				& powercfg.exe /setactive SCHEME_MIN 2>$null;
			}
		} catch {
			& powercfg.exe /setactive SCHEME_MIN 2>$null;
		}
	};
	{
		# AtlasOS & ReviOS: Low-Latency BCD Boot & Timer Tweaks
		try {
			& bcdedit.exe /set useplatformclock false 2>$null;
			& bcdedit.exe /set disabledynamictick yes 2>$null;
			& bcdedit.exe /set tscsyncpolicy Enhanced 2>$null;
			& bcdedit.exe /timeout 0 2>$null;
			if (Test-Path "C:\Windows\Setup\Scripts\no-hypervisor.flag") {
				& bcdedit.exe /set hypervisorlaunchtype off 2>$null;
			}
		} catch {}
	};
	{
		# AtlasOS & ReviOS: Advanced Low-Latency Network & Nagle Tuning
		try {
			& netsh.exe int tcp set global autotuninglevel=normal 2>$null;
			& netsh.exe int tcp set global rss=enabled 2>$null;
			& netsh.exe int tcp set global rsc=disabled 2>$null;
			& netsh.exe int tcp set global ecncapability=enabled 2>$null;
			& netsh.exe int tcp set global timestamps=disabled 2>$null;
			& netsh.exe int tcp set heuristics disabled 2>$null;
			$adapters = Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\*' -ErrorAction SilentlyContinue;
			foreach ($adapter in $adapters) {
				Set-ItemProperty -Path $adapter.PSPath -Name 'TcpAckFrequency' -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue;
				Set-ItemProperty -Path $adapter.PSPath -Name 'TCPNoDelay' -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue;
			}
			if (Test-Path "C:\Windows\Setup\Scripts\disable-netbios.flag") {
				Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Services\NetBT\Parameters\Interfaces' -ErrorAction SilentlyContinue |
					ForEach-Object { Set-ItemProperty $_.PSPath 'NetbiosOptions' 2 -Type DWord -Force -ErrorAction SilentlyContinue };
			}
		} catch {}
	};
	{
		# AtlasOS & ReviOS: NTFS I/O Overhead Reduction
		try {
			& fsutil.exe behavior set disablelastaccess 1 2>$null;
			& fsutil.exe 8dot3name set 1 2>$null;
		} catch {}
	};
	{
		# AtlasOS & ReviOS: Generate Desktop Maintenance & Toggle Scripts
		try {
			$toolsDir = "$env:PUBLIC\Desktop\Atlas-ReviOS Tools";
			New-Item -ItemType Directory -Force -Path $toolsDir -ErrorAction SilentlyContinue | Out-Null;

			# 1. Toggle Windows Defender
			@'
@echo off
setlocal
echo ========================================================
echo   Atlas/ReviOS Tool: Toggle Windows Defender
echo ========================================================
sc query WinDefend | find "RUNNING" >nul
if %errorlevel% equ 0 (
    echo Disabling Windows Defender...
    reg add "HKLM\SOFTWARE\Policies\Microsoft\Windows Defender" /v DisableAntiSpyware /t REG_DWORD /d 1 /f >nul 2>&1
    reg add "HKLM\SOFTWARE\Policies\Microsoft\Windows Defender\Real-Time Protection" /v DisableRealtimeMonitoring /t REG_DWORD /d 1 /f >nul 2>&1
    sc config WinDefend start= disabled >nul 2>&1
    sc stop WinDefend >nul 2>&1
    echo Windows Defender has been DISABLED.
) else (
    echo Enabling Windows Defender...
    reg delete "HKLM\SOFTWARE\Policies\Microsoft\Windows Defender" /v DisableAntiSpyware /f >nul 2>&1
    reg delete "HKLM\SOFTWARE\Policies\Microsoft\Windows Defender\Real-Time Protection" /v DisableRealtimeMonitoring /f >nul 2>&1
    sc config WinDefend start= auto >nul 2>&1
    sc start WinDefend >nul 2>&1
    echo Windows Defender has been ENABLED.
)
pause
'@ | Set-Content -LiteralPath "$toolsDir\1. Toggle Windows Defender.bat" -Encoding ascii;

			# 2. Toggle Windows Update
			@'
@echo off
setlocal
echo ========================================================
echo   Atlas/ReviOS Tool: Toggle Windows Update
echo ========================================================
sc query wuauserv | find "RUNNING" >nul
if %errorlevel% equ 0 (
    echo Disabling Windows Update...
    sc config wuauserv start= disabled >nul 2>&1
    sc stop wuauserv >nul 2>&1
    sc config UsoSvc start= disabled >nul 2>&1
    sc stop UsoSvc >nul 2>&1
    sc config WaaSMedicSvc start= disabled >nul 2>&1
    sc stop WaaSMedicSvc >nul 2>&1
    reg add "HKLM\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU" /v NoAutoUpdate /t REG_DWORD /d 1 /f >nul 2>&1
    echo Windows Update has been DISABLED.
) else (
    echo Enabling Windows Update...
    sc config wuauserv start= demand >nul 2>&1
    sc start wuauserv >nul 2>&1
    sc config UsoSvc start= demand >nul 2>&1
    sc config WaaSMedicSvc start= demand >nul 2>&1
    reg delete "HKLM\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU" /v NoAutoUpdate /f >nul 2>&1
    echo Windows Update has been ENABLED.
)
pause
'@ | Set-Content -LiteralPath "$toolsDir\2. Toggle Windows Update.bat" -Encoding ascii;

			# 3. Toggle Hibernation
			@'
@echo off
setlocal
echo ========================================================
echo   Atlas/ReviOS Tool: Toggle Hibernation
echo ========================================================
if exist "%SystemDrive%\hiberfil.sys" (
    echo Disabling Hibernation and deleting hiberfil.sys...
    powercfg.exe /h off
    echo Hibernation is now DISABLED (Disk space freed).
) else (
    echo Enabling Hibernation...
    powercfg.exe /h on
    echo Hibernation is now ENABLED.
)
pause
'@ | Set-Content -LiteralPath "$toolsDir\3. Toggle Hibernation.bat" -Encoding ascii;

			# 4. Toggle Bluetooth
			@'
@echo off
setlocal
echo ========================================================
echo   Atlas/ReviOS Tool: Toggle Bluetooth Services
echo ========================================================
sc query bthserv | find "RUNNING" >nul
if %errorlevel% equ 0 (
    echo Disabling Bluetooth...
    sc config bthserv start= disabled >nul 2>&1
    sc stop bthserv >nul 2>&1
    sc config BthAvctpSvc start= disabled >nul 2>&1
    sc stop BthAvctpSvc >nul 2>&1
    echo Bluetooth services DISABLED.
) else (
    echo Enabling Bluetooth...
    sc config bthserv start= auto >nul 2>&1
    sc start bthserv >nul 2>&1
    sc config BthAvctpSvc start= auto >nul 2>&1
    sc start BthAvctpSvc >nul 2>&1
    echo Bluetooth services ENABLED.
)
pause
'@ | Set-Content -LiteralPath "$toolsDir\4. Toggle Bluetooth.bat" -Encoding ascii;

			# 5. Toggle Print Spooler
			@'
@echo off
setlocal
echo ========================================================
echo   Atlas/ReviOS Tool: Toggle Print Spooler
echo ========================================================
sc query Spooler | find "RUNNING" >nul
if %errorlevel% equ 0 (
    echo Disabling Print Spooler...
    sc config Spooler start= disabled >nul 2>&1
    sc stop Spooler >nul 2>&1
    echo Print Spooler is now DISABLED.
) else (
    echo Enabling Print Spooler...
    sc config Spooler start= auto >nul 2>&1
    sc start Spooler >nul 2>&1
    echo Print Spooler is now ENABLED.
)
pause
'@ | Set-Content -LiteralPath "$toolsDir\5. Toggle Print Spooler.bat" -Encoding ascii;

			# 6. Free Memory & Clear Temp
			@'
@echo off
setlocal
echo ========================================================
echo   Atlas/ReviOS Tool: Free Memory & Clear Temp
echo ========================================================
echo Cleaning temporary files...
del /s /f /q "%TEMP%\*.*" >nul 2>&1
del /s /f /q "%SystemRoot%\Temp\*.*" >nul 2>&1
powershell.exe -NoProfile -Command "try { $sig = '[DllImport(\"psapi.dll\")] public static extern int EmptyWorkingSet(IntPtr h);'; Add-Type -MemberDefinition $sig -Name 'Mem' -Namespace 'Win32' -ErrorAction SilentlyContinue; Get-Process | ForEach-Object { try { [Win32.Mem]::EmptyWorkingSet($_.Handle) | Out-Null } catch {} }; [GC]::Collect(); Write-Host 'RAM working set trimmed successfully.' -ForegroundColor Green } catch {}"
echo Done.
pause
'@ | Set-Content -LiteralPath "$toolsDir\6. Free Memory & Clear Temp.bat" -Encoding ascii;

			# 7. Browser Grabber (Zero-Byte Fast Browser Installer on Public Desktop)
			@'
@echo off
setlocal
title nano11 - Web Browser Installer
color 0b
echo ========================================================
echo   nano11 Fast Web Browser Installer
echo ========================================================
echo.
echo  Select a modern web browser to install:
echo.
echo   [1] Google Chrome
echo   [2] Mozilla Firefox
echo   [3] Brave Browser
echo   [4] Floorp Browser
echo   [5] Microsoft Edge (Reinstall)
echo   [0] Exit
echo.
set /p choice="Enter choice [0-5]: "
if "%choice%"=="1" (
    echo Downloading and installing Google Chrome...
    powershell.exe -NoProfile -Command "Invoke-WebRequest -Uri 'https://dl.google.com/chrome/install/latest/chrome_installer.exe' -OutFile '$env:TEMP\chrome_setup.exe' -UseBasicParsing; Start-Process '$env:TEMP\chrome_setup.exe' -ArgumentList '/silent /install' -Wait"
    echo Chrome installed successfully!
)
if "%choice%"=="2" (
    echo Downloading and installing Mozilla Firefox...
    powershell.exe -NoProfile -Command "Invoke-WebRequest -Uri 'https://download.mozilla.org/?product=firefox-latest-ssl&os=win64&lang=en-US' -OutFile '$env:TEMP\firefox_setup.exe' -UseBasicParsing; Start-Process '$env:TEMP\firefox_setup.exe' -ArgumentList '/S' -Wait"
    echo Firefox installed successfully!
)
if "%choice%"=="3" (
    echo Downloading and installing Brave Browser...
    powershell.exe -NoProfile -Command "Invoke-WebRequest -Uri 'https://laptop-updates.brave.com/latest/winx64' -OutFile '$env:TEMP\brave_setup.exe' -UseBasicParsing; Start-Process '$env:TEMP\brave_setup.exe' -ArgumentList '/silent /install' -Wait"
    echo Brave installed successfully!
)
if "%choice%"=="4" (
    echo Downloading and installing Floorp Browser...
    powershell.exe -NoProfile -Command "try { $rel = Invoke-RestMethod -Uri 'https://api.github.com/repos/Floorp-Projects/Floorp/releases/latest'; $asset = $rel.assets | Where-Object { $_.name -like '*win64*installer.exe' -or $_.name -like '*win64.installer.exe' } | Select-Object -First 1; if ($asset) { Invoke-WebRequest -Uri $asset.browser_download_url -OutFile '$env:TEMP\floorp_setup.exe' -UseBasicParsing; Start-Process '$env:TEMP\floorp_setup.exe' -ArgumentList '/S' -Wait; Write-Host 'Floorp installed!' -ForegroundColor Green } } catch {}"
)
if "%choice%"=="5" (
    echo Downloading and installing Microsoft Edge...
    powershell.exe -NoProfile -Command "Invoke-WebRequest -Uri 'https://go.microsoft.com/fwlink/?linkid=2108834&Channel=Stable&language=en' -OutFile '$env:TEMP\EdgeSetup.exe' -UseBasicParsing; Start-Process '$env:TEMP\EdgeSetup.exe' -ArgumentList '/silent /install' -Wait"
    echo Edge installed successfully!
)
pause
'@ | Set-Content -LiteralPath "$env:PUBLIC\Desktop\Install-Browser.cmd" -Encoding ascii;

			# 8. Unified nano11 Control Center on Public Desktop
			@'
@echo off
setlocal
title nano11 System Control Center
:MENU
cls
color 0b
echo ========================================================
echo   nano11 System Control Center
echo ========================================================
echo.
echo   [1] Toggle Windows Defender
echo   [2] Toggle Windows Update
echo   [3] Toggle Hibernation (Free Disk Space)
echo   [4] Toggle Bluetooth Services
echo   [5] Toggle Print Spooler
echo   [6] Free RAM ^& Clear Temporary Files
echo   [7] Install Web Browser
echo   [8] Open Atlas / ReviOS Tools Folder
echo   [0] Exit
echo.
set /p sel="Enter option [0-8]: "
if "%sel%"=="1" call "%~dp0Atlas-ReviOS Tools\1. Toggle Windows Defender.bat" & goto MENU
if "%sel%"=="2" call "%~dp0Atlas-ReviOS Tools\2. Toggle Windows Update.bat" & goto MENU
if "%sel%"=="3" call "%~dp0Atlas-ReviOS Tools\3. Toggle Hibernation.bat" & goto MENU
if "%sel%"=="4" call "%~dp0Atlas-ReviOS Tools\4. Toggle Bluetooth.bat" & goto MENU
if "%sel%"=="5" call "%~dp0Atlas-ReviOS Tools\5. Toggle Print Spooler.bat" & goto MENU
if "%sel%"=="6" call "%~dp0Atlas-ReviOS Tools\6. Free Memory & Clear Temp.bat" & goto MENU
if "%sel%"=="7" call "%~dp0Install-Browser.cmd" & goto MENU
if "%sel%"=="8" explorer.exe "%~dp0Atlas-ReviOS Tools" & goto MENU
if "%sel%"=="0" exit /b
goto MENU
'@ | Set-Content -LiteralPath "$env:PUBLIC\Desktop\nano11-Control-Center.cmd" -Encoding ascii;
		} catch {}
	};
	{
		# Custom Post-Install User Scripts Execution Hook (from tools/custom-scripts/)
		$customDir = "C:\Windows\Setup\Scripts\Custom";
		if (Test-Path $customDir) {
			Get-ChildItem -Path $customDir -File | Sort-Object Name | ForEach-Object {
				try {
					switch ($_.Extension.ToLower()) {
						'.ps1' { & powershell.exe -ExecutionPolicy Bypass -NoProfile -File $_.FullName }
						'.bat' { & cmd.exe /c "`"$($_.FullName)`"" }
						'.cmd' { & cmd.exe /c "`"$($_.FullName)`"" }
						'.reg' { & reg.exe import $_.FullName }
					}
				} catch {}
			}
		}
	};
	{
		# Post-OOBE WebView2 removal if flagged
		if (Test-Path "C:\Windows\Setup\Scripts\remove-webview.flag") {
			try {
				Remove-Item 'C:\Windows\System32\Microsoft-Edge-WebView' -Recurse -Force -ErrorAction SilentlyContinue;
				Remove-Item "C:\Windows\Setup\Scripts\remove-webview.flag" -Force -ErrorAction SilentlyContinue;
			} catch {}
		}
	};
	{
		# Boot Time Metrics Tracking (Event ID 100)
		try {
			$bootEvent = Get-WinEvent -FilterHashtable @{LogName='Microsoft-Windows-Diagnostics-Performance/Operational'; Id=100} -MaxEvents 1 -ErrorAction SilentlyContinue;
			if ($bootEvent -and $bootEvent.Properties -and $bootEvent.Properties.Count -gt 0) {
				$bootMs = $bootEvent.Properties[0].Value;
				$statsDir = "C:\ProgramData\nano11";
				if (-not (Test-Path $statsDir)) { New-Item -ItemType Directory -Force -Path $statsDir | Out-Null; }
				"{0},{1:N0}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $bootMs | Add-Content "$statsDir\boot-stats.csv";
			}
		} catch {}
	};
	{
		# WinRE Online Dismantle if winre-cleanup.flag is present
		$flag = "C:\Windows\Setup\Scripts\winre-cleanup.flag";
		if (Test-Path $flag) {
			try {
				& reagentc.exe /disable 2>$null;
				$winrePath = "C:\Windows\System32\Recovery\Winre.wim";
				if (Test-Path $winrePath) {
					takeown.exe /f $winrePath /a 2>$null;
					icacls.exe $winrePath /grant "*S-1-5-32-544:F" 2>$null;
					Remove-Item -LiteralPath $winrePath -Force -ErrorAction SilentlyContinue;
				}
				Remove-Item -LiteralPath $flag -Force -ErrorAction SilentlyContinue;
			} catch {}
		}
	};
	{
		# Signal FirstLogon completion and restore persistent AutoLogon security
		try {
			$markerDir = "C:\ProgramData\nano11";
			if (-not (Test-Path $markerDir)) { New-Item -ItemType Directory -Force -Path $markerDir | Out-Null; }
			Set-Content -LiteralPath "$markerDir\firstlogon.done" -Value (Get-Date -Format "yyyy-MM-dd HH:mm:ss") -Encoding ascii;

			# Security restore: Tear down permanent AutoLogon after setup logon succeeds
			Set-ItemProperty -LiteralPath 'Registry::HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'AutoAdminLogon' -Value '0' -Force -ErrorAction SilentlyContinue;
			Set-ItemProperty -LiteralPath 'Registry::HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'ForceAutoLogon' -Value '0' -Force -ErrorAction SilentlyContinue;
			Remove-ItemProperty -LiteralPath 'Registry::HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'DefaultPassword' -Force -ErrorAction SilentlyContinue;
		} catch {}
	};
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Activity 'Running scripts to finalize your Windows installation. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command "{0}".' -f $(
      $str = $script.ToString().Trim() -replace '\s+', ' ';
      $max = 100;
      if( $str.Length -le $max ) {
        $str;
      } else {
        $str.Substring( 0, $max - 1 ) + '...';
      }
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 >> "C:\Windows\Setup\Scripts\FirstLogon.log";
